-- Script 231 · Organizaciones 4 (Tecnoalsa) y 7 (AAPOS): 10037 líneas del detalle contable de las compras del sistema anterior
--   (ACT_DETCON_COMPRAS.xlsx). Lógica del script 200. Se ejecuta después del script 229 (compras).
--   Cada línea se liga a su compra por el número del sistema anterior; LINEA = línea; la cuenta se busca por su código en la versión
--   VERSION del catálogo de la localidad (script 222). CENTRO = centro de costo (0 = sin centro; los que no existen se crean).
--   DEBITO = debe, CREDITO = haber. Líneas con débito y crédito a la vez: ninguna.
--   No se migran 0 líneas de las compras sin valor total. DEBITO_MI y CREDITO_MI vienen vacías.
--   Para el SQL Editor de Supabase están por separado en supabase/pendientes/231_compras_contable_parte_N_de_7.sql (primero la parte 0).

-- Script 231 · parte 0 de 7 · Organizaciones 4 y 7: columnas del detalle contable de compras. Se ejecuta UNA vez, antes de las partes 1 a 7.
set lock_timeout = '20s';
do $col$
declare r record; v_n int := 0;
begin
  for r in select * from (values ('cuenta_codigo_anterior', 'text'), ('version_cuenta_anterior', 'integer'), ('centro_costo_anterior', 'text'),
                                 ('debe_anterior', 'numeric(18, 2)'), ('haber_anterior', 'numeric(18, 2)'), ('reconstruida', 'boolean not null default false')) as x(col, tipo)
  loop
    if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'compra_lineas' and column_name = r.col) then
      execute format('alter table public.compra_lineas add column %I %s', r.col, r.tipo);
      v_n := v_n + 1;
    end if;
  end loop;
  raise notice '%', format('Detalle contable de compras: %s columnas nuevas (las demás ya existían).', v_n);
end;
$col$;
-- Si el sistema reconstruyó líneas contables en estas compras migradas (script 168), se reemplazan por las del sistema anterior:
-- se borran aquí, una sola vez. No se tocan las compras que no traen detalle contable (437 de la 4, 87 de la 7).
